import { type Plugin, tool } from "@opencode-ai/plugin"
import type { Browser, BrowserContext, Page } from "playwright"
import fs from "fs"
import os from "os"
import path from "path"
import { spawn } from "node:child_process"
import { createRequire } from "node:module"
import { fileURLToPath } from "url"

type PlaywrightModule = typeof import("playwright")

function pluginRoot(): string {
  // dist/plugin.js -> package root; src/plugin.ts -> package root too
  const here = path.dirname(fileURLToPath(import.meta.url))
  return path.basename(here) === "dist" ? path.join(here, "..") : here
}

let playwrightModule: PlaywrightModule | null = null

function hasPlaywrightOnDisk(): boolean {
  const root = pluginRoot()
  return (
    fs.existsSync(path.join(root, "node_modules", "playwright", "package.json")) ||
    fs.existsSync(path.join(root, "..", "node_modules", "playwright", "package.json"))
  )
}

async function selfHealInstall(): Promise<void> {
  const root = pluginRoot()
  const cacheDir = path.join(os.tmpdir(), "opencode-bun-cache")
  fs.mkdirSync(cacheDir, { recursive: true })
  const envPatch = { BUN_INSTALL_CACHE_DIR: cacheDir, CI: "1" } as Record<string, string>
  const install = (command: string, ms: number) =>
    new Promise<boolean>((resolve) => {
      const child = spawn(command, { cwd: root, shell: true, stdio: "ignore", env: { ...process.env, ...envPatch } })
      let done = false
      const finish = (ok: boolean) => {
        if (done) return
        done = true
        clearTimeout(timer)
        resolve(ok)
      }
      const timer = setTimeout(() => {
        try { child.kill("SIGKILL") } catch {}
        finish(false)
      }, ms)
      child.on("exit", (code) => finish(code === 0))
      child.on("error", () => finish(false))
    })
  if (!hasPlaywrightOnDisk()) await install(`bun add playwright@^1.64.0`, 45000)
  if (!hasPlaywrightOnDisk())
    await install(`npm install playwright@^1.64.0 --no-audit --no-fund --loglevel=error`, 120000)
}

async function loadPlaywright(): Promise<PlaywrightModule> {
  if (playwrightModule) return playwrightModule
  // IMPORTANT: never `import("playwright")` speculatively. If the package is
  // missing, bun's runtime auto-install kicks in and can hang for minutes on
  // slow package caches; and after a fresh install, bun's async ESM loader
  // can stall on the new files. require() via createRequire is instant and
  // deterministic, resolved from this plugin's own directory.
  if (!hasPlaywrightOnDisk()) await selfHealInstall()
  if (!hasPlaywrightOnDisk()) {
    throw new Error(
      "opencode-browser-kit could not install playwright. Run manually in the plugin's folder: `bun add playwright && bunx playwright install chromium` (or use system Chrome/Edge).",
    )
  }
  playwrightModule = createRequire(import.meta.url)("playwright") as PlaywrightModule
  return playwrightModule
}

let browser: Browser | null = null
let context: BrowserContext | null = null
let page: Page | null = null

const SCREENSHOT_DIR = path.join(os.tmpdir(), "opencode-browser-screenshots")
const VIEWPORT = { width: 1280, height: 800 }

async function launchBrowser(headless = true): Promise<Browser> {
  const { chromium } = await loadPlaywright()
  const attempts: { channel?: string }[] = [
    {},
    { channel: "chrome" },
    { channel: "msedge" },
  ]
  let lastError: unknown
  for (const opts of attempts) {
    try {
      return await chromium.launch({ headless, ...opts })
    } catch (e) {
      lastError = e
    }
  }
  throw new Error(
    `Could not launch any Chromium. Tried default install and system Chrome/Edge. ${String(lastError)}`,
  )
}

async function ensurePage(): Promise<Page> {
  if (!browser || !browser.isConnected()) {
    browser = await launchBrowser()
    context = await browser.newContext({
      viewport: VIEWPORT,
      deviceScaleFactor: 2,
    })
    context.setDefaultTimeout(20000)
    page = await context.newPage()
  }
  if (!context || !page || page.isClosed()) {
    page = await context!.newPage()
  }
  return page!
}

function resolveSelector(target: string): string {
  const t = target.trim()
  if (
    /^(text=|css=|xpath=|role=|label=|id=|\/{1,2}|\.\.)/i.test(t) ||
    /^[.#*[\]]/.test(t)
  ) {
    return t
  }
  const looksCss =
    /^(html|head|body|div|span|a|button|input|textarea|select|form|img|svg|main|nav|header|footer|section|article|ul|ol|li|table|tr|td|th|h[1-6]|p|label|iframe|dialog)([.#\[:\s>]|$)/i.test(
      t,
    ) || /^[\w-]+$/i.test(t)
  if (looksCss) return t
  return `text=${t}`
}

async function saveScreenshot(
  p: Page,
  label: string,
  fullPage = false,
): Promise<string> {
  fs.mkdirSync(SCREENSHOT_DIR, { recursive: true })
  const file = path.join(SCREENSHOT_DIR, `${label}-${Date.now()}.png`)
  await p.screenshot({ path: file, fullPage })
  return file
}

function formatSnap(file: string): string {
  return `\n\nScreenshot saved: ${file}\n(Use the read tool on that path to view it.)`
}

const PICKER_JS = `(function () {
  if (window.__ocPickerActive) return
  window.__ocPickerActive = true
  window.__ocPicked = undefined
  var CSS_TXT =
    '.oc-ph { outline: 2px solid #e11d48 !important; outline-offset: -2px !important; cursor: crosshair !important; }' +
    '.oc-panel { position: fixed; z-index: 2147483647; right: 16px; top: 16px; width: 340px; box-sizing: border-box; font: 13px/1.45 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #fff; color: #111; border-radius: 10px; box-shadow: 0 8px 30px rgba(0,0,0,.28); padding: 12px 14px; }' +
    '.oc-panel .oc-tag { font-weight: 600; font-size: 13px; }' +
    '.oc-panel .oc-sel { color: #888; font: 11px ui-monospace, SFMono-Regular, Menlo, monospace; word-break: break-all; margin-top: 2px; }' +
    '.oc-panel .oc-txt { color: #444; font-size: 12px; margin-top: 4px; max-height: 48px; overflow: hidden; }' +
    '.oc-panel textarea { width: 100%; height: 70px; box-sizing: border-box; margin: 10px 0 8px; padding: 8px; border: 1px solid #ddd; border-radius: 6px; font: inherit; resize: vertical; }' +
    '.oc-btns { display: flex; gap: 8px; }' +
    '.oc-btns button { flex: 1; padding: 7px 10px; border-radius: 6px; border: 1px solid #ddd; background: #fff; color: #111; font: inherit; cursor: pointer; }' +
    '.oc-btns button[data-a="apply"] { background: #111; color: #fff; border-color: #111; }'
  var style = document.createElement('style')
  style.textContent = CSS_TXT
  style.setAttribute('data-oc', '1')
  document.head.appendChild(style)

  var banner = document.createElement('div')
  banner.className = 'oc-panel'
  banner.textContent = 'Click any element to select it · Esc to cancel'
  document.documentElement.appendChild(banner)

  var picking = true
  var last = null

  function hover(e) {
    if (!picking) return
    if (last) last.classList.remove('oc-ph')
    last = null
    var el = document.elementFromPoint(e.clientX, e.clientY)
    if (el && el !== document.documentElement && el !== document.body && !(el.closest && el.closest('.oc-panel'))) {
      last = el
      el.classList.add('oc-ph')
    }
  }

  function selFor(el) {
    if (el.dataset && el.dataset.testid) return '[data-testid="' + el.dataset.testid + '"]'
    var parts = []
    var node = el
    while (node && node.nodeType === 1 && node !== document.body) {
      var p = node.nodeName.toLowerCase()
      if (node.id) { parts.unshift('#' + CSS.escape(node.id)); break }
      var cl = Array.prototype.filter
        .call(node.classList, function (c) { return !c.startsWith('oc-') })
        .slice(0, 2)
        .map(function (c) { return '.' + CSS.escape(c) })
        .join('')
      p += cl
      if (node.parentElement) {
        var sib = Array.prototype.filter.call(node.parentElement.children, function (c) { return c.nodeName === node.nodeName })
        if (sib.length > 1) p += ':nth-of-type(' + (sib.indexOf(node) + 1) + ')'
      }
      parts.unshift(p)
      node = node.parentElement
    }
    return parts.join(' > ') || 'body'
  }

  function reactInfo(el) {
    try {
      for (var k in el) {
        if (k.indexOf('__reactFiber$') === 0) {
          var f = el[k]
          var name = null
          while (f) {
            if (f._debugSource) {
              return { file: f._debugSource.fileName, line: f._debugSource.lineNumber, comp: name || '' }
            }
            var t = f.type || f.elementType
            if (typeof t === 'function' && !name) name = t.displayName || t.name
            f = f.return
          }
          return { comp: name || '' }
        }
      }
    } catch (err) {}
    return null
  }

  function collect(el) {
    var cs = getComputedStyle(el)
    var r = el.getBoundingClientRect()
    return {
      selector: selFor(el),
      tag: el.tagName.toLowerCase(),
      id: el.id || '',
      classes: Array.prototype.filter.call(el.classList, function (c) { return !c.startsWith('oc-') }).join(' '),
      text: (el.innerText || '')
        .split('\\n')
        .map(function (t) { return t.trim() })
        .filter(Boolean)
        .slice(0, 3)
        .join(' | ')
        .slice(0, 150),
      html: el.outerHTML.slice(0, 400),
      rect: { x: Math.round(r.x), y: Math.round(r.y), width: Math.round(r.width), height: Math.round(r.height) },
      styles: {
        fontSize: cs.fontSize,
        fontWeight: cs.fontWeight,
        color: cs.color,
        backgroundColor: cs.backgroundColor,
        borderRadius: cs.borderRadius,
        fontFamily: cs.fontFamily,
      },
      react: reactInfo(el),
    }
  }

  function mk(a, label) {
    var b = document.createElement('button')
    b.setAttribute('data-a', a)
    b.textContent = label
    return b
  }

  function openPanel(el, info) {
    if (last) last.classList.remove('oc-ph')
    last = el
    el.classList.add('oc-ph')
    banner.remove()
    var panel = document.createElement('div')
    panel.className = 'oc-panel'
    var tag = document.createElement('div')
    tag.className = 'oc-tag'
    tag.textContent = '<' + info.tag + '>' + (info.id ? ' #' + info.id : info.classes ? ' ' + info.classes : '')
    var path = document.createElement('div')
    path.className = 'oc-sel'
    path.textContent = info.selector
    var txt = document.createElement('div')
    txt.className = 'oc-txt'
    txt.textContent = info.text || ''
    var ta = document.createElement('textarea')
    ta.placeholder = 'Describe what you want changed…'
    ta.setAttribute('data-oc-ta', '1')
    var btns = document.createElement('div')
    btns.className = 'oc-btns'
    btns.append(mk('apply', 'Apply'), mk('reselect', 'Reselect'), mk('cancel', 'Cancel'))
    panel.append(tag, path, txt, ta, btns)
    document.documentElement.appendChild(panel)
    ta.focus()
    panel.addEventListener('mousedown', function (e) { e.stopPropagation() })
    panel.addEventListener('click', function (e) {
      var a = e.target.getAttribute && e.target.getAttribute('data-a')
      if (a === 'apply') finish(Object.assign({}, info, { note: ta.value.trim() }))
      else if (a === 'cancel') finish(null)
      else if (a === 'reselect') {
        panel.remove()
        picking = true
        document.documentElement.appendChild(banner)
        document.addEventListener('mousemove', hover, true)
      }
    })
  }

  function down(e) {
    if (!picking || e.button !== 0) return
    var el = document.elementFromPoint(e.clientX, e.clientY)
    if (!el || (el.closest && el.closest('.oc-panel'))) return
    e.preventDefault()
    e.stopPropagation()
    picking = false
    document.removeEventListener('mousemove', hover, true)
    openPanel(el, collect(el))
  }

  function esc(e) {
    if (e.key === 'Escape') { e.preventDefault(); finish(null) }
  }

  function blockClick(e) {
    if (e.target.closest && e.target.closest('.oc-panel')) return
    e.preventDefault()
    e.stopPropagation()
  }

  function finish(val) { cleanup(); window.__ocPicked = val }

  function cleanup() {
    picking = false
    document.removeEventListener('mousemove', hover, true)
    document.removeEventListener('mousedown', down, true)
    document.removeEventListener('keydown', esc, true)
    document.removeEventListener('click', blockClick, true)
    Array.prototype.forEach.call(document.querySelectorAll('.oc-ph'), function (n) { n.classList.remove('oc-ph') })
    Array.prototype.forEach.call(document.querySelectorAll('.oc-panel'), function (n) { n.remove() })
    var st = document.querySelector('style[data-oc]')
    if (st) st.remove()
    window.__ocPickerActive = false
  }

  document.addEventListener('mousemove', hover, true)
  document.addEventListener('mousedown', down, true)
  document.addEventListener('keydown', esc, true)
  document.addEventListener('click', blockClick, true)
})()`

export const BrowserPlugin: Plugin = async (ctx) => {
  return {
    tool: {
      browser_navigate: tool({
        description:
          "Navigate the embedded headless browser to a URL. Returns page title plus a screenshot path you can view with the read tool. The browser session persists across tool calls.",
        args: {
          url: tool.schema
            .string()
            .describe("Full URL, e.g. https://example.com or http://localhost:3000"),
        },
        async execute(args) {
          const p = await ensurePage()
          try {
            await p.goto(args.url, { waitUntil: "networkidle", timeout: 20000 })
          } catch {
            await p.goto(args.url, { waitUntil: "domcontentloaded", timeout: 20000 })
          }
          const title = await p.title()
          const file = await saveScreenshot(p, "navigate")
          return `Navigated to ${p.url()}\nTitle: ${title}${formatSnap(file)}`
        },
      }),

      browser_snapshot: tool({
        description:
          "Read the currently open page's content as text (title, url, visible text). Optionally scope to a CSS/text selector.",
        args: {
          selector: tool.schema
            .string()
            .optional()
            .describe(
              "Optional CSS or text= selector to scope the snapshot to a region, e.g. main or text=Pricing",
            ),
          maxLength: tool.schema
            .number()
            .optional()
            .describe("Max characters of text to return (default 8000)"),
        },
        async execute(args) {
          const p = await ensurePage()
          const scope = args.selector ? resolveSelector(args.selector) : "body"
          const text = await p.evaluate(
            ({ sel }) => {
              const el = document.querySelector(sel)
              if (!el) return null
              return (el as HTMLElement).innerText
            },
            { sel: scope },
          )
          if (text === null) {
            return `No element matched "${scope}" on ${p.url()}`
          }
          const max = args.maxLength ?? 8000
          const trimmed =
            text.length > max ? text.slice(0, max) + "\n…[truncated]" : text
          return `URL: ${p.url()}\nTitle: ${await p.title()}\n\n---\n${trimmed}`
        },
      }),

      browser_click: tool({
        description:
          "Click an element in the browser. Accepts a CSS selector (#id, .class, button), xpath (//button[2]), or plain text (wrapped as text= automatically). A screenshot is saved after clicking.",
        args: {
          target: tool.schema
            .string()
            .describe('e.g. "#submit", "a", //button[2], "Sign in"'),
        },
        async execute(args) {
          const p = await ensurePage()
          const selector = resolveSelector(args.target)
          await p.click(selector, { timeout: 15000 })
          await p.waitForLoadState("domcontentloaded").catch(() => {})
          const file = await saveScreenshot(p, "click")
          return `Clicked "${selector}" on ${p.url()}${formatSnap(file)}`
        },
      }),

      browser_type: tool({
        description:
          "Type text into a form field. Clears existing value, types the text, and optionally presses Enter to submit.",
        args: {
          target: tool.schema
            .string()
            .describe('Field selector, e.g. "input[name=q]" or "Search"'),
          text: tool.schema.string().describe("Text to type"),
          submit: tool.schema
            .boolean()
            .optional()
            .describe("Press Enter after typing (default false)"),
        },
        async execute(args) {
          const p = await ensurePage()
          const selector = resolveSelector(args.target)
          await p.fill(selector, args.text, { timeout: 15000 })
          if (args.submit) {
            await p.press(selector, "Enter")
            await p.waitForLoadState("domcontentloaded").catch(() => {})
          }
          const file = await saveScreenshot(p, "type")
          return `Typed ${JSON.stringify(args.text)} into "${selector}" (submit=${!!args.submit})${formatSnap(file)}`
        },
      }),

      browser_screenshot: tool({
        description:
          "Take a screenshot of the current browser page. Returns the file path; use the read tool to view it.",
        args: {
          fullPage: tool.schema
            .boolean()
            .optional()
            .describe("Capture the full scrollable page (default: viewport only)"),
        },
        async execute(args) {
          const p = await ensurePage()
          const file = await saveScreenshot(p, "shot", !!args.fullPage)
          return `Screenshot of ${p.url()} saved: ${file}`
        },
      }),

      browser_close: tool({
        description: "Close the embedded browser and release its resources.",
        args: {},
        async execute() {
          if (browser) {
            await browser.close().catch(() => {})
            browser = null
            context = null
            page = null
          }
          return "Browser closed."
        },
      }),

      browser_inspect: tool({
        description:
          "Interactive element picker for design changes. Opens a VISIBLE browser window on the URL, waits for the user to hover and CLICK an element, then the user TYPES what they want changed and clicks Apply. Returns the element's unique selector, text, HTML, styles, React component source (when available) and the user's change note. Use whenever the user wants to point at something on the page to modify it.",
        args: {
          url: tool.schema
            .string()
            .describe("URL to open, e.g. http://localhost:3000"),
          timeoutSeconds: tool.schema
            .number()
            .optional()
            .describe("How long to wait for the user's selection (default 300)"),
        },
        async execute(args) {
          let inspectBrowser: Browser | null = null
          try {
            const { chromium } = await loadPlaywright()
            inspectBrowser = await launchBrowser(false)
            const pageCtx = await inspectBrowser.newContext({
              viewport: VIEWPORT,
              deviceScaleFactor: 1,
            })
            pageCtx.setDefaultTimeout(30000)
            const p = await pageCtx.newPage()
            await p.goto(args.url, { waitUntil: "domcontentloaded", timeout: 30000 })
            await p.evaluate(PICKER_JS)
            try {
              await p.waitForFunction("window.__ocPicked !== undefined", null, {
                timeout: (args.timeoutSeconds ?? 300) * 1000,
                polling: 200,
              })
            } catch {
              return "No selection made within the timeout — visible browser closed."
            }
            const outcome = (await p.evaluate("window.__ocPicked")) as
              | null
              | {
                  note: string
                  selector: string
                  tag: string
                  id: string
                  classes: string
                  text: string
                  html: string
                  rect: { x: number; y: number; width: number; height: number }
                  styles: Record<string, string>
                  react: { file?: string; line?: number; comp?: string } | null
                }
            if (outcome === null) return "Selection cancelled by user."
            const lines = [
              `User picked an element on ${p.url()}`,
              `Selector: ${outcome.selector}`,
              `Tag: ${outcome.tag}${outcome.id ? ` #${outcome.id}` : ""}${outcome.classes ? ` (${outcome.classes})` : ""}`,
              `Text: ${outcome.text || "(none)"}`,
              `Box: ${outcome.rect.width}x${outcome.rect.height} at (${outcome.rect.x}, ${outcome.rect.y})`,
              `Styles: fontSize=${outcome.styles.fontSize} fontWeight=${outcome.styles.fontWeight} color=${outcome.styles.color} background=${outcome.styles.backgroundColor} radius=${outcome.styles.borderRadius} font=${(outcome.styles.fontFamily || "").split(",")[0]}`,
              `HTML: ${outcome.html}`,
              outcome.react?.file
                ? `React source: ${outcome.react.file}${outcome.react.line ? `:${outcome.react.line}` : ""}${outcome.react.comp ? ` (${outcome.react.comp})` : ""}`
                : null,
              `User note: ${outcome.note || "(nothing typed — ask the user what to change)"}`,
            ].filter(Boolean)
            return lines.join("\n")
          } finally {
            if (inspectBrowser) await inspectBrowser.close().catch(() => {})
          }
        },
      }),
    },
  }
}
